export function formatNutrition(
  calories: number | null,
  protein: number | null,
  fiber: number | null,
): string {
  const parts: string[] = []
  if (calories != null) parts.push(`~${calories} cal`)
  if (protein != null) parts.push(`${protein}g protein`)
  if (fiber != null) parts.push(`${fiber}g fiber`)
  return parts.length ? parts.join(', ') + ' per serving' : ''
}

export function formatIngredient(
  quantity: string | null,
  name: string,
  notes: string | null,
): string {
  let result = quantity ? `${quantity} ${name}` : name
  if (notes) result += notes.startsWith('(') ? ` ${notes}` : `, ${notes}`
  return result
}
